private void pop(String descriptor) {
    if (descriptor.equals("V")) {
        // No types to pop
        return;
    }
    char type = descriptor.charAt(0);
    switch (type) {
        case '[':
            // Pop array type
            arrayTypes.pop();
            break;
        case 'L':
            // Pop object type
            classTypes.pop();
            break;
        case 'Z':
        case 'B':
        case 'C':
        case 'S':
        case 'I':
        case 'J':
        case 'F':
        case 'D':
            // Pop primitive type
            primitiveTypes.pop();
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

