private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        Object type = currentFrame.getType(i);
        if (type instanceof String) {
            // If the type is a class name, we need to convert it to the JVMS
            // verification_type_info format.
            String className = (String) type;
            String descriptor = ReflectionUtils.arrayTypeName(className);
            stackMapTableEntries.add(new StackMapFrameType(descriptor));
        } else if (type instanceof Integer) {
            // If the type is an integer, we need to convert it to a
            // verification_type_info format for the value.
            int intValue = (Integer) type;
