    for (int i = 0; i < count; i++) {
        Integer bound = bounds.get(i);
        if (bound == null) {
            throw new IllegalArgumentException("bounds list must not contain null elements");
        }
        suffixSums.add(bound);
        sum += bound;
    }

    // Step 3: Compute total sum and return result pair
    return new Pair<>(suffixSums, sum);
}

