    index++;
    byte b1 = bb.get(index++);
    byte b2 = bb.get(index++);
    sb.append((char) (((b1 & 0x1F) << 6) | (b2 & 0x3F)));
  } else if (type == 0xE0) {
    // 3-byte encoding
    index++;
    byte b1 = bb.get(index++);
    byte b2 = bb.get(index++);
    byte b3 = bb.get(index++);
    sb.append((char) (((b1 & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
