    for (int i = 0; i < typeArguments.length; i++) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) typeArguments[i];
        Class<?> resolvedClass = targetType.resolveTypeVariable(typeVariable.getName());
        if (resolvedClass != null) {
