public static AtmosphereRequest wrap(HttpServletRequest request) {
    AtmosphereRequest atmosRequest = new AtmosphereRequest();
    atmosRequest.setMethod(request.getMethod());
    Enumeration<String> headerNames = request.getHeaderNames();
    while (headerNames.hasMoreElements()) {
        String headerName = headerNames.nextElement();
        String headerValue = request.getHeader(headerName);
        atmosRequest.addHeader(headerName, headerValue);
    }
    Enumeration<String> queryNames = request.getParameterNames();
    while (queryNames.hasMoreElements()) {
        String queryName = queryNames.nextElement();
        String[] values = request.getParameterValues(queryName);
        for (String value : values) {
            atmosRequest.addQuery(queryName, value);
        }
    }
    atmosRequest.setUrl(request.getRequestURL().toString());
    return atmosRequest;
}

