public static String applyRelativePath(String path, String relativePath) {
  // Start by splitting the relative path into its components
  List<String> relativePathComponents = Arrays.asList(relativePath.split("/"));

  // Iterate over the components and apply them to the path
  for (String component : relativePathComponents) {
    if (component.equals("..")) {
      // If the component is "..", we need to go up one directory
      path = getParentDirectory(path);
    } else if (!component.isEmpty()) {
      // If the component is not ".." or empty, we can just append it to the path
      path += "/" + component;
    }
  }

  return path;
}

