public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Before step, handle input edge cases
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("Time bucket must be a positive value");
    }
    if (dayStep <= 0 || dayStep > 30) {
        throw new IllegalArgumentException("Day step must be a positive integer between 1 and 30");
    }

    // Divide the time bucket by the day step to get the number of days
    int numDays = (int) (timeBucket / dayStep);

    // If the number of days is 0, set the time bucket to the start of the day (i.e., 0)
    if (numDays == 0) {
        return 0;
    }

    // Get the day of the week (Mon = 0, Sun = 6)
    int dayOfWeek = (int) (timeBucket % 7);

    // Get the number of days since the start of the week
    int daysSinceStartOfWeek = dayOfWeek * dayStep;

    // Calculate the starting day of the week
    int startingDayOfWeek = numDays - daysSinceStartOfWeek;

    // Calculate the number of days since the start of the month
    int numDaysSinceStartOfMonth = startingDayOfWeek % 30;

    // If the number of days since the start of the month is 0, set the time bucket to the start of the month (i.e., 1)
    if (numDaysSinceStartOfMonth == 0) {
        return 1;
    }

    // Otherwise, calculate the time bucket
    return (startingDayOfWeek - numDaysSinceStartOfMonth + 1) * dayStep;
}

