public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check if file is null
    if (file == null) {
        throw new NullPointerException("file is null");
    }
    // Check if timeRanges is null or empty
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("timeRanges is null or empty");
    }
    // Parse the file and extract the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        for (String line = reader.readLine(); line != null; line = reader.readLine()) {
            if (line.startsWith("Thread snapshot")) {
                ThreadSnapshot snapshot = ThreadSnapshot.parseFromString(line);
                threadSnapshots.add(snapshot);
            }
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
    // Filter the thread snapshots based on the time ranges
    List<ThreadSnapshot> filteredSnapshots = new ArrayList<>();
    for (ThreadSnapshot snapshot : threadSnapshots) {
        int startTime = snapshot.getStartTime();
        int endTime = snapshot.getEndTime();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (startTime >= range.getStartTime() && endTime <= range.getEndTime()) {
                filteredSnapshots.add(snapshot);
                break;
            }
        }
    }
    return filteredSnapshots;
}

