    if (str == null) {
        throw new NullPointerException("The string argument cannot be null.");
    }
    if (session == null) {
        throw new NullPointerException("The session argument cannot be null.");
    }
    if (lb == null) {
        throw new NullPointerException("The LinkedBuffer argument cannot be null.");
    }

    // Compute the length of the UTF-8 encoded bytes
    int utf8Length = Utf8Encoder.encodeUTF8Length(str);

    // Allocate a byte buffer of the required size
    byte[] bytes = new byte[utf8Length];

    // Encode the string into UTF-8
    Utf8Encoder.encodeUTF8(str, bytes, 0, utf8Length);

    // Write the encoded bytes to the LinkedBuffer
    session.writeBuffer(bytes, 0, bytes.length);

    // Return the updated LinkedBuffer
    return lb;
}

